// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Genel ek sorular: Ekonomi ve Finans kategorisinde bankada henüz sorulmamış bilgi ve beceriler (bu kategorinin alt alanları: Temel ekonomi kavramları: arz-talep, piyasa, üretim | Para, bankacılık, enflasyon, faiz ve kişisel finans | Uluslararası ekonomi, ticaret ve ekonomi tarihi | Girişimcilik, işletme, muhasebe ve vergi temel kavramları) (orta).
const ozEconomics5Orta = <(String, String, List<String>, String)>[
  ('Çalışma çağındaki nüfusu 60 milyon olan bir ülkede 27 milyon kişi istihdamda, 3 milyon kişi işsizdir. İşgücüne katılma oranı yüzde kaçtır?', '50', ['45', '10', '100'], 'İşgücü istihdam ile işsizlerin toplamıdır: 27 + 3 = 30 milyon. Katılma oranı 30/60 = yüzde 50\'dir.'),
  ('Uzun süre iş arayıp bulamayan ve sonunda aramayı bırakan bir kişi resmî işgücü istatistiklerinde nasıl ele alınır?', 'İşgücü dışında sayılır ve işsizlik oranını düşürür', ['İşsiz sayılır ve işsizlik oranını yükseltir', 'İstihdamda sayılır ve oranlar hiç değişmez', 'Hem işsiz hem işgücü dışı olarak iki kez sayılır'], 'İş aramayan kişi işsiz tanımına girmez; işgücü dışına çıktığı için işsizlik oranı, gerçek durumdan daha iyi görünebilir. Bu kişilere ümidi kırılmış işçi denir.'),
  ('Beş kişilik bir aile tarlasında çalışıyor; iki kişi şehre göç ettiğinde tarladan alınan ürün hiç azalmıyor. Göç edenlerin önceki durumu hangi kavramla açıklanır?', 'Gizli işsizlik', ['Mevsimlik işsizlik', 'Friksiyonel işsizlik', 'Eksik değerleme'], 'Marjinal ürünü sıfır olan, görünüşte çalışıp gerçekte üretime katkı yapmayan işgücüne gizli işsizlik denir; tarımda sık görülür.'),
  ('Açık iş (boş kadro) oranı ile işsizlik oranı arasındaki ters ilişkiyi gösteren eğriye ne ad verilir?', 'Beveridge eğrisi', ['Phillips eğrisi', 'Lorenz eğrisi', 'Laffer (vergi) eğrisi'], 'Beveridge eğrisi boş kadrolar arttığında işsizliğin azaldığını gösterir; eğrinin dışa kayması eşleşmenin kötüleştiğine işaret eder.'),
  ('Uzun süren bir durgunlukta işsiz kalanların becerilerini ve iş bağlantılarını yitirmesi sonucu ekonomi düzelse bile işsizliğin yüksek kalmasına ne ad verilir?', 'Histerezis', ['Likidite tuzağı', 'Para yanılsaması', 'Dışlama etkisi'], 'Histerezis, geçici bir şokun kalıcı izler bırakmasıdır; uzun süreli işsizlik doğal işsizlik oranını yükseltebilir.'),
  ('İş arayanlarla boş kadroları hızla buluşturan çevrim içi istihdam platformlarının yaygınlaşması en çok hangi işsizlik türünü azaltır?', 'Friksiyonel işsizlik', ['Konjonktürel işsizlik', 'Mevsimlik işsizlik', 'Teknolojik işsizlik'], 'İş arama süresini kısaltan bilgi akışı, eşleşme sürecinden kaynaklanan friksiyonel işsizliği azaltır.'),
  ('Tam zamanlı çalışmak istediği hâlde yalnızca haftada 15 saatlik iş bulabilen bir kişinin durumu hangi kavramla anlatılır?', 'Eksik istihdam', ['Gizli işsizlik', 'Friksiyonel işsizlik', 'İşgücü dışılık'], 'İstediğinden az saat ya da niteliğinin altında bir işte çalışan kişi istihdamda sayılır ama eksik istihdam edilmiş olur.'),
  ('Asgari ücret piyasadaki denge ücretinin üzerinde belirlenirse basit arz-talep modeline göre emek piyasasında ne beklenir?', 'Emek arzı emek talebini aşar ve işsizlik oluşur', ['Emek talebi arzı aşar ve işgücü açığı doğar', 'Ücret kendiliğinden denge düzeyine geri iner', 'İstihdam artar ve işsizlik tamamen ortadan kalkar'], 'Bağlayıcı asgari ücret bir taban fiyat gibi davranır; o ücretten çalışmak isteyen sayısı firmaların istediği işçi sayısını aşar.'),
  ('Bazı firmaların piyasa ücretinin üzerinde ücret ödeyerek işçilerin daha verimli çalışmasını ve işten ayrılmamasını sağlamaya çalışmasını açıklayan yaklaşım hangisidir?', 'Etkin ücret kuramı', ['Ücret fonu kuramı', 'Demir ücret yasası', 'Emek-değer kuramı'], 'Etkin (verimlilik) ücret kuramına göre yüksek ücret, işçi devrini ve gözetim maliyetini azaltıp verimliliği artırır; bu da ücretlerin dengenin üzerinde kalmasına yol açabilir.'),
  ('Bir firma üretim düzeyini sabit tutarak bir birim sermayeden vazgeçtiğinde kaç birim fazladan emek kullanması gerektiğini gösteren orana ne ad verilir?', 'Marjinal teknik ikame oranı', ['Marjinal ikame oranı', 'Sermaye-hasıla oranı', 'Emeğin ortalama ürünü'], 'Marjinal teknik ikame oranı izokuantın eğimidir ve iki girdinin marjinal ürünlerinin oranına eşittir.'),
  ('Bir uçak fabrikasında üretilen toplam uçak sayısı arttıkça işçilerin deneyim kazanmasıyla uçak başına maliyetin düşmesi hangi kavramla açıklanır?', 'Öğrenme eğrisi etkisi', ['Azalan verimler yasası', 'Ölçeğe göre azalan getiri', 'Kapsam ekonomisi'], 'Öğrenme eğrisi, birikimli üretim arttıkça kazanılan deneyimin birim maliyeti düşürmesini anlatır; uçak ve yarı iletken üretiminde belirgindir.'),
  ('Uzun dönem ortalama maliyetin en düşük düzeyine ilk kez ulaşıldığı en küçük üretim miktarına ne ad verilir?', 'Asgari etkin ölçek', ['Başabaş noktası', 'Kapatma noktası', 'Optimal stok düzeyi'], 'Asgari etkin ölçek, ölçek ekonomilerinin tükendiği üretim düzeyidir; bu ölçek piyasa talebine göre büyükse sektörde az sayıda firma barınır.'),
  ('Bir sektörde dört firmanın pazar payları yüzde 40, 30, 20 ve 10\'dur. Bu sektörün Herfindahl-Hirschman endeksi (HHI) kaçtır?', '3.000', ['1.000', '2.500', '10.000'], 'HHI pazar paylarının karelerinin toplamıdır: 1600 + 900 + 400 + 100 = 3000.'),
  ('Herfindahl-Hirschman endeksinin 10.000 değerini alması piyasa hakkında ne anlatır?', 'Piyasada tek bir firma vardır', ['Piyasa tam rekabet koşullarındadır', 'Piyasada eşit büyüklükte iki firma vardır', 'Piyasada yüz firma eşit pay sahibidir'], 'Tek firmanın payı yüzde 100 olduğunda HHI = 100² = 10.000 olur; bu en yüksek yoğunlaşma, yani tekeldir.'),
  ('Bir firmanın sattığı ürünün fiyatı 50 TL, marjinal maliyeti 30 TL\'dir. Bu firmanın Lerner tekel gücü endeksi kaçtır?', '0,4', ['0,6', '1,67', '20'], 'Lerner endeksi (P − MC) / P\'dir: (50 − 30) / 50 = 0,4. Tam rekabette fiyat marjinal maliyete eşit olduğundan endeks sıfırdır.'),
  ('Bir sinemanın aynı film için öğrencilere ve emeklilere düşük, diğer izleyicilere yüksek bilet fiyatı uygulaması hangi tür fiyat farklılaştırmasıdır?', 'Üçüncü derece fiyat farklılaştırması', ['Birinci derece fiyat farklılaştırması', 'İkinci derece fiyat farklılaştırması', 'Yıkıcı fiyatlandırma'], 'Tüketicilerin gözlenebilir özelliklere göre gruplara ayrılıp her gruba farklı fiyat uygulanması üçüncü derece fiyat farklılaştırmasıdır.'),
  ('Oligopol modellerinden hangisinde firmalar rakiplerinin üretim miktarını veri alarak kendi üretim miktarlarını eş zamanlı olarak belirler?', 'Cournot modeli', ['Bertrand modeli', 'Stackelberg modeli', 'Dirsekli talep modeli'], 'Cournot modelinde rekabet miktar üzerinden yapılır ve kararlar eş zamanlıdır; Bertrand\'da fiyat, Stackelberg\'de ise sıralı karar söz konusudur.'),
  ('Aynı ürünü aynı maliyetle üreten iki firmanın fiyat üzerinden rekabet ettiği Bertrand modelinde denge fiyatı nereye yerleşir?', 'Marjinal maliyete', ['Tekel fiyatına', 'Marjinal maliyetin iki katına', 'Ortalama sabit maliyete'], 'Her firma rakibinin biraz altında fiyat koyarak tüm pazarı alabileceği için fiyatlar marjinal maliyete kadar iner; buna Bertrand paradoksu denir.'),
  ('Bir firmanın önce üretim miktarını açıkladığı, rakibinin ise bu miktarı görüp ardından kendi kararını verdiği oligopol modeline ne ad verilir?', 'Stackelberg modeli', ['Cournot modeli', 'Bertrand modeli', 'Dirsekli talep (Sweezy) modeli'], 'Stackelberg modelinde önce karar veren firma lider, sonra tepki veren firma izleyicidir; lider ilk hareket avantajı elde eder.'),
  ('Bir piyasaya giriş ve çıkış maliyetsizse, içeride tek bir firma olsa bile bu firmanın aşırı kâr elde edemeyeceğini savunan yaklaşım hangisidir?', 'Yarışılabilir piyasalar kuramı', ['Doğal tekel kuramı', 'Dirsekli talep kuramı', 'Ortak kaynak kuramı'], 'Yarışılabilir piyasalarda olası rakiplerin vur-kaç girişi tehdidi, mevcut firmayı rekabetçi fiyata yakın fiyat koymaya zorlar.'),
  ('Bir ülkede herkes yolun sağından gidiyorsa sizin için de sağdan gitmek, herkes soldan gidiyorsa soldan gitmek en iyisidir. Bu durum oyun teorisinde hangi tür oyuna örnektir?', 'Koordinasyon oyunu', ['Sıfır toplamlı oyun', 'Mahkûm ikilemi', 'Tavuk oyunu'], 'Koordinasyon oyunlarında oyuncuların aynı stratejiyi seçmesi herkes için kazançlıdır; birden fazla denge (hepsi sağ ya da hepsi sol) bulunabilir.'),
  ('Sıralı hamleli oyunlarda dengeyi bulmak için oyunun son hamlesinden başlayıp her aşamada en iyi seçimi belirleyerek başa doğru ilerleme yöntemine ne ad verilir?', 'Geriye doğru tümevarım', ['Baskın strateji eleme', 'Karma strateji', 'Maksimin kuralı'], 'Geriye doğru tümevarımda önce son karar vericinin en iyi tepkisi bulunur, sonra bir önceki oyuncunun bunu öngörerek seçimi yapılır.'),
  ('Bir oyuncunun rakibinin kafasını karıştırmak için seçeneklerini belirli olasılıklarla rastgele seçmesine, örneğin bir penaltıcının köşeleri değişken oranlarla tercih etmesine, ne ad verilir?', 'Karma strateji', ['Baskın strateji', 'Saf strateji', 'Tetik stratejisi'], 'Karma stratejide oyuncu saf stratejiler arasında olasılık dağılımına göre seçim yapar; saf strateji dengesi olmayan oyunlarda karma strateji dengesi bulunabilir.'),
  ('Durgunluk döneminde vergi gelirlerinin kendiliğinden azalması ve işsizlik ödemelerinin kendiliğinden artması gibi, yeni bir karar alınmadan talebi destekleyen mekanizmalara ne ad verilir?', 'Otomatik stabilizatörler', ['İhtiyari maliye politikası', 'Açık piyasa işlemleri', 'Dengeli bütçe kuralı'], 'Otomatik stabilizatörler meclis kararı gerektirmeden iş çevrimlerinin etkisini yumuşatır; artan oranlı gelir vergisi ve işsizlik sigortası başlıca örneklerdir.'),
  ('Hükümetin açığını kapatmak için yoğun borçlanması faizleri yükseltip özel sektör yatırımlarını azaltıyorsa bu duruma ne ad verilir?', 'Dışlama (crowding out) etkisi', ['Çarpan etkisi', 'Hızlandıran (akselerasyon) etkisi', 'Servet etkisi'], 'Kamunun ödünç verilebilir fonlara talebi faizi artırır; daha pahalı kredi özel yatırımları kısarak genişletici maliye politikasının etkisini zayıflatır.'),
  ('Bir hükümet vergileri indirip açığı borçla kapattığında hanehalklarının gelecekteki vergi artışını öngörüp harcamalarını değiştirmeyerek tasarrufu artıracağını savunan görüş hangisidir?', 'Ricardocu denklik', ['Laffer etkisi', 'Wagner yasası', 'Tasarruf paradoksu'], 'Ricardocu denkliğe göre borçla finanse edilen vergi indirimi ileride yükselecek vergilerin bugünkü değerine eşit olduğundan tüketimi artırmaz. Görüş Robert Barro tarafından modern biçimde savunulmuştur.'),
  ('Bir ülkenin bütçe gelirleri 900 milyar, faiz ödemeleri hariç harcamaları 850 milyar, faiz ödemeleri ise 150 milyar liradır. Faiz dışı (birincil) denge ve toplam bütçe dengesi hangisidir?', '50 milyar fazla; 100 milyar açık', ['100 milyar açık; 50 milyar fazla', '50 milyar açık; 100 milyar fazla', '150 milyar fazla; 50 milyar açık'], 'Faiz dışı denge 900 − 850 = +50 milyardır. Toplam denge 900 − (850 + 150) = −100 milyar, yani 100 milyar açıktır.'),
  ('Ekonomi potansiyel düzeyinde çalışsaydı ortaya çıkacak bütçe açığına, yani konjonktürün etkisinden arındırılmış açığa ne ad verilir?', 'Yapısal bütçe açığı', ['Konjonktürel bütçe açığı', 'Birincil bütçe açığı', 'Cari işlemler açığı'], 'Yapısal açık, durgunluk ya da canlanmanın gelir ve giderler üzerindeki geçici etkisi çıkarıldıktan sonra kalan kalıcı açıktır.'),
  ('Bir ülkede nominal GSYH 1.320 milyar lira, reel GSYH 1.100 milyar liradır. GSYH deflatörü kaçtır?', '120', ['83', '110', '220'], 'GSYH deflatörü (nominal GSYH / reel GSYH) × 100\'dür: 1320 / 1100 × 100 = 120. Bu, temel yıla göre fiyatların yüzde 20 arttığını gösterir.'),
  ('Gini katsayısı Lorenz eğrisi kullanılarak nasıl hesaplanır?', 'Eşitlik doğrusu ile Lorenz eğrisi arasındaki alanın eşitlik doğrusu altındaki toplam alana oranıyla', ['Lorenz eğrisinin eğiminin bire bölünmesiyle', 'En zengin yüzde 10\'un gelirinin toplam gelire oranıyla', 'Lorenz eğrisinin altındaki alanın iki katıyla'], 'Eşitlik doğrusuyla Lorenz eğrisi arasındaki alan A, eğrinin altındaki alan B ise Gini = A / (A + B) olur.'),
  ('Simon Kuznets\'in ileri sürdüğü, kalkınmanın ilk aşamalarında gelir eşitsizliğinin arttığını, daha ileri aşamalarda ise azaldığını anlatan ilişki hangi biçimde gösterilir?', 'Ters U biçiminde bir eğriyle', ['Sürekli yükselen bir doğruyla', 'U biçiminde bir eğriyle', 'Yatay bir doğruyla'], 'Kuznets eğrisi kişi başı gelir yatay eksende, eşitsizlik dikey eksende olmak üzere ters U biçimindedir; ampirik geçerliliği tartışılsa da kavram olarak böyle tanımlanır.'),
  ('Bir ülkenin GSYH\'si 800 milyar dolar, yurt dışında çalışan vatandaşlarının ve şirketlerinin elde ettiği faktör gelirleri 30 milyar dolar, yabancıların bu ülkede elde edip dışarı aktardığı faktör gelirleri 50 milyar dolardır. Ülkenin GSMH\'si kaçtır?', '780 milyar dolar', ['820 milyar dolar', '880 milyar dolar', '750 milyar dolar'], 'GSMH = GSYH + yurt dışından alınan net faktör gelirleri = 800 + 30 − 50 = 780 milyar dolar.'),
  ('Solow modeline göre kişi başına gelirin uzun dönemde sürekli artmasını sağlayabilecek tek kaynak hangisidir?', 'Teknolojik ilerleme', ['Sermaye birikimi', 'Nüfus artışı', 'Tasarruf oranının artması'], 'Sermaye birikimi azalan getiriye tabidir; bu yüzden modelde kişi başı gelirin sürekli büyümesi dışsal teknolojik ilerlemeye bağlıdır.'),
  ('Benzer tasarruf oranı ve teknolojiye sahip yoksul ülkelerin zengin ülkelerden daha hızlı büyüyerek zamanla onları yakalaması beklentisine ne ad verilir?', 'Koşullu yakınsama', ['Kaynak laneti', 'Ters sanayisizleşme', 'Orta gelir tuzağı'], 'Solow modelinde sermayesi az olan ekonomide sermayenin marjinal getirisi yüksektir; benzer yapıdaki ülkelerin aynı durağan duruma yaklaşması koşullu yakınsamadır.'),
  ('Harrod-Domar modeline göre tasarruf oranı yüzde 20, sermaye-hasıla katsayısı 4 olan bir ekonominin büyüme hızı yüzde kaçtır?', '5', ['80', '24', '16'], 'Harrod-Domar modelinde büyüme hızı tasarruf oranının sermaye-hasıla katsayısına bölümüdür: 20 / 4 = yüzde 5.'),
  ('Ragnar Nurkse\'nin \'Bir ülke yoksuldur, çünkü yoksuldur.\' sözüyle özetlenen görüş hangi kavramı anlatır?', 'Yoksulluğun kısır döngüsü', ['Kaynak laneti', 'Kalkış aşaması', 'Yaratıcı yıkım'], 'Düşük gelir düşük tasarruf ve yatırıma, bu da düşük verimlilik ve yine düşük gelire yol açar; Nurkse bu döngünün kırılması için dengeli büyümeyi önermiştir.'),
  ('Bir ülkede büyümenin sermaye ve emek artışıyla açıklanamayan, verimlilik artışından kaynaklanan kısmına ne ad verilir?', 'Toplam faktör verimliliği', ['Sermaye derinleşmesi', 'Marjinal tüketim eğilimi', 'Potansiyel çıktı açığı'], 'Büyüme muhasebesinde girdilerin katkısı çıkarıldıktan sonra kalan kısım (Solow artığı) toplam faktör verimliliği olarak adlandırılır.'),
  ('Bir yatırımcı kullanım fiyatı 100 lira olan bir hisse alım opsiyonunu 6 lira prim ödeyerek almıştır. Vade sonunda hisse 115 liradan işlem görüyorsa yatırımcının bu işlemden net kârı kaç liradır?', '9', ['15', '21', '6'], 'Opsiyon kullanılırsa kazanç 115 − 100 = 15 liradır; ödenen 6 liralık prim düşülünce net kâr 9 lira olur.'),
  ('Aynı alım opsiyonunda (kullanım fiyatı 100 lira, prim 6 lira) vade sonunda hisse fiyatı 90 lira olursa yatırımcının en büyük zararı ne olur?', 'Yalnızca ödediği 6 liralık prim', ['Hisse başına 10 lira', 'Prim artı 10 lira, toplam 16 lira', 'Zarar sınırsızdır'], 'Hisse kullanım fiyatının altındayken alım opsiyonu kullanılmaz; opsiyon alıcısının zararı ödediği primle sınırlıdır.'),
  ('İngiliz iktisatçı Walter Bagehot\'un 1873\'te önerdiği kurala göre merkez bankası bir panik sırasında bankalara nasıl kredi vermelidir?', 'İyi teminat karşılığında, cezalandırıcı yüksek faizle ve bol miktarda', ['Teminatsız ve faizsiz, yalnızca büyük bankalara', 'Hiç kredi vermeyip bankaların batmasına izin vererek', 'Yalnızca kamu bankalarına, piyasa faizinin altında'], 'Bagehot\'un \'Lombard Street\' kitabındaki ilke, son kredi mercinin likiditeyi esirgememesini ama ahlaki tehlikeyi sınırlamak için yüksek faiz istemesini öngörür.'),
  ('Bir bankanın batması tüm finansal sistemi sarsacağı için devletin onu kurtarmak zorunda kalacağı beklentisine dayanan sorun hangi deyimle anılır?', 'Batamayacak kadar büyük', ['Kaçamayacak kadar küçük', 'Son kredi mercii ilkesi', 'Gölge bankacılık sorunu'], 'Kurtarılacağını bilen büyük bankalar aşırı risk almaya yönelebilir; bu bir ahlaki tehlike sorunudur ve 2008 krizinden sonra sıkça tartışılmıştır.'),
  ('Tek tek bankaların değil, finansal sistemin bütününün istikrarını korumayı amaçlayan, kredi büyümesini sınırlama gibi politikalara ne ad verilir?', 'Makro ihtiyati politikalar', ['Mikro ihtiyati politikalar', 'Genişletici maliye politikaları', 'Gelirler politikası'], 'Makro ihtiyati araçlar arasında kredi/değer oranı sınırları ve döngü karşıtı sermaye tamponları yer alır; amaç sistemik riski azaltmaktır.'),
  ('Bugün 1.000 lira yatırım gerektiren bir proje bir yıl sonra tek seferde 1.210 lira nakit getirecektir. İskonto oranı yüzde 10 ise projenin net bugünkü değeri kaç liradır?', '100', ['210', '110', '0'], 'Gelecekteki nakdin bugünkü değeri 1210 / 1,1 = 1100 liradır; yatırım düşülünce net bugünkü değer 1100 − 1000 = 100 lira olur.'),
  ('Bugün 2.000 liraya mal olan bir makine bir yıl sonra 2.300 liralık nakit getirip hurdaya çıkacaktır. Bu yatırımın iç verim oranı yüzde kaçtır?', '15', ['13', '30', '11,5'], '2000 × (1 + r) = 2300 eşitliğinden r = 300 / 2000 = 0,15, yani yüzde 15 bulunur.'),
  ('Basit geri ödeme süresi yöntemine yöneltilen temel eleştiri hangisidir?', 'Paranın zaman değerini ve geri ödemeden sonraki nakit akışlarını dikkate almaz', ['Hesaplanması için iskonto oranını bilmek gerekir', 'Yalnızca kısa ömürlü projelerde sonuç verir', 'Nakit akışları yerine muhasebe kârını kullanır'], 'Geri ödeme süresi, yatırımı en kısa sürede çıkaran projeyi öne çıkarır; ancak daha sonra gelecek büyük nakitleri ve iskontolamayı göz ardı eder.'),
  ('Bir fonun yıllık ortalama getirisi yüzde 14, risksiz faiz oranı yüzde 4 ve getirilerinin standart sapması yüzde 20\'dir. Fonun Sharpe oranı kaçtır?', '0,5', ['0,7', '0,2', '0,25'], 'Sharpe oranı (fon getirisi − risksiz getiri) / standart sapmadır: (14 − 4) / 20 = 0,5. Oran, üstlenilen her birim risk başına ek getiriyi gösterir.'),
  ('Bir şirketin önemli bir dava kaybetme olasılığını finansal tabloların dipnotlarında açıklaması hangi muhasebe kavramının gereğidir?', 'Tam açıklama kavramı', ['Maliyet esası kavramı', 'Dönemsellik kavramı', 'Parayla ölçülme kavramı'], 'Tam açıklama kavramına göre tablo kullanıcılarının kararlarını etkileyebilecek bütün bilgiler açık ve anlaşılır biçimde sunulmalıdır.'),
  ('Faiz ve vergi öncesi kârı 900.000 lira, yıllık faiz giderleri 300.000 lira olan bir şirketin faiz karşılama oranı kaçtır?', '3', ['0,33', '1,5', '6'], 'Faiz karşılama oranı faiz ve vergi öncesi kârın faiz giderine bölümüdür: 900.000 / 300.000 = 3. Şirket faizini kârıyla üç kez karşılayabilmektedir.'),
  ('Net satışları 2 milyon lira, toplam varlıkları 800.000 lira olan bir şirketin aktif devir hızı kaçtır?', '2,5', ['0,4', '1,6', '0,25'], 'Aktif devir hızı net satışların toplam varlıklara oranıdır: 2.000.000 / 800.000 = 2,5. Her bir lira varlık 2,5 liralık satış yaratmaktadır.'),
  ('Toplam talep-toplam arz modelinde hanehalklarının servetindeki ani bir düşüş, örneğin borsanın çökmesi, kısa dönemde nasıl bir etki yaratır?', 'Toplam talep sola kayar; üretim ve fiyat düzeyi düşer', ['Toplam arz sola kayar; fiyatlar yükselir, üretim düşer', 'Toplam talep sağa kayar; fiyatlar ve üretim yükselir', 'Toplam arz sağa kayar; fiyatlar düşer, üretim artar'], 'Servet kaybı tüketimi azaltarak toplam talep eğrisini sola kaydırır; kısa dönem arz eğrisi boyunca hem üretim hem fiyat düzeyi geriler.'),
  ('Petrol fiyatlarının dünya genelinde ani ve sert biçimde yükselmesi toplam talep-toplam arz modelinde kısa dönemde hangi sonucu doğurur?', 'Fiyat düzeyi yükselirken üretim azalır', ['Fiyat düzeyi ve üretim birlikte artar', 'Fiyat düzeyi düşerken üretim artar', 'Yalnızca toplam talep eğrisi sağa kayar'], 'Girdi maliyetlerini artıran olumsuz arz şoku kısa dönem toplam arz eğrisini sola kaydırır; bu, enflasyonla durgunluğun bir arada görüldüğü stagflasyona yol açabilir.'),
  ('Gerçekleşen üretimin potansiyel üretimden yüzde 3 düşük olduğu bir ekonomi için hangi ifade doğrudur?', 'Negatif çıktı açığı vardır ve işsizlik doğal oranın üzerindedir', ['Pozitif çıktı açığı vardır ve enflasyon baskısı artar', 'Ekonomi tam istihdamda ve potansiyel düzeyindedir', 'Potansiyel üretim kalıcı olarak yüzde 3 azalmıştır'], 'Gerçekleşen üretim potansiyelin altındaysa çıktı açığı negatiftir; atıl kapasite ve doğal oranın üzerinde işsizlik görülür.'),
  ('Enflasyonu kalıcı olarak bir puan düşürmek için katlanılması gereken yıllık üretim kaybı yüzdesinin toplamına ne ad verilir?', 'Fedakârlık oranı', ['Okun katsayısı', 'Phillips eğrisinin eğimi', 'Vergi takozu'], 'Fedakârlık oranı dezenflasyonun reel maliyetini ölçer; örneğin oran 2 ise enflasyonu bir puan düşürmek toplam yüzde 2 GSYH kaybına mal olur.'),
  ('1976\'da ortaya atılan ve geçmiş verilerden tahmin edilen ilişkilerin politika değiştiğinde de geçerli kalacağını varsaymanın yanıltıcı olduğunu söyleyen eleştiri hangisidir?', 'Lucas eleştirisi', ['Leontief paradoksu', 'Triffin ikilemi', 'Easterlin paradoksu'], 'Lucas eleştirisine göre insanlar beklentilerini yeni politikaya göre değiştirdiğinden, eski davranış kalıplarına dayanan modeller politika etkisini yanlış tahmin eder.'),
  ('İnsanların gelecekteki enflasyonu esas olarak geçmişte gerçekleşen enflasyona bakarak ve hatalarını yavaş yavaş düzelterek tahmin ettiğini varsayan beklenti türü hangisidir?', 'Uyarlayıcı beklentiler', ['Rasyonel beklentiler', 'Durağan (statik) beklentiler', 'Çapalanmış beklentiler'], 'Uyarlayıcı beklentilerde beklenti, önceki tahmin hatasının bir kısmı kadar düzeltilir; Friedman ve Phelps\'in doğal oran açıklamasında bu yaklaşım kullanılmıştır.'),
  ('Milton Friedman\'ın sürekli gelir hipotezine göre bir kişi piyangodan bir kez büyük para kazandığında tüketimini nasıl değiştirir?', 'Tüketimini az artırır, kazancın çoğunu zamana yayar', ['Kazancın tamamını aynı yıl içinde tüketime harcar', 'Tüketimini hiç değiştirmez ve parayı saklar', 'Tüketimini kazancın iki katı kadar artırır'], 'Friedman\'a göre tüketim geçici gelire değil uzun dönemli ortalama (sürekli) gelire bağlıdır; geçici gelir artışının büyük kısmı tasarruf edilir.'),
  ('Franco Modigliani\'nin yaşam boyu gelir hipotezine göre insanlar çalışma yıllarında neden tasarruf eder?', 'Emeklilik döneminde tüketimlerini düzgün sürdürebilmek için', ['Gelirleri arttıkça daha fazla vergi ödememek için', 'Komşularının tüketim düzeyine yetişmek için', 'Faiz oranları düştükçe daha çok kazanmak için'], 'Yaşam boyu hipotezi tüketicilerin ömür boyu tüketimlerini dengelediğini, çalışırken biriktirip emeklilikte birikimlerini kullandığını öne sürer.'),
  ('James Duesenberry\'nin nispi gelir hipotezine göre bir hanenin tüketimini en çok ne etkiler?', 'Hanenin gelirinin çevresindeki hanelerin gelirine göre konumu', ['Yalnızca o yılki mutlak gelir düzeyi', 'Faiz oranlarındaki yıllık değişmeler ve beklentiler', 'Emeklilik yaşına kadar kalan süre'], 'Duesenberry\'ye göre tüketim alışkanlıklar ve gösteriş etkisiyle başkalarının tüketimine bağlıdır; gelir düşse bile tüketim kolayca azaltılmaz (mandal etkisi).'),
  ('James Tobin\'in q oranı, bir şirketin piyasa değerinin varlıklarının yerine koyma maliyetine oranıdır. Bu oranın 1\'den büyük olması firmaya ne işaret eder?', 'Yeni yatırım yapmak kârlıdır', ['Varlıklarını satması gerekir', 'Hisse senedi değer kaybedecektir', 'Yatırımlarını durdurması gerekir'], 'q > 1 ise piyasa yeni sermayeye maliyetinden fazla değer biçmektedir; yeni makine ve tesis almak firmanın değerini artırır.'),
  ('Keynes\'in para talebi güdülerinden hangisi, insanların faiz oranlarının yükselip tahvil fiyatlarının düşeceğini beklediklerinde elde daha çok para tutmasını açıklar?', 'Spekülasyon güdüsü', ['İşlem güdüsü', 'İhtiyat güdüsü', 'Değer ölçüsü güdüsü'], 'Spekülasyon güdüsüne göre tahvil fiyatlarının düşmesi beklenirken para tutmak sermaye kaybından korur; bu yüzden para talebi faize duyarlıdır.'),
  ('16. yüzyılda Habsburg imparatorlarına büyük krediler açan ve Kutsal Roma İmparatoru V. Karl\'ın seçilmesini finanse eden Augsburglu tüccar ve bankacı aile hangisidir?', 'Fugger', ['Medici', 'Rothschild', 'Bardi'], 'Jakob Fugger\'in önderliğinde aile maden işletmeciliği ve bankacılıkla dönemin en zengin ailelerinden biri olmuş, 1519 imparatorluk seçimini kredileriyle desteklemiştir.'),
  ('Almanya\'da 1923\'te yaşanan hiperenflasyon, Kasım 1923\'te bir yeni birimin bir trilyon eski marka eşit tutulduğu hangi para birimiyle durdurulmuştur?', 'Rentenmark', ['Reichsmark', 'Deutsche Mark', 'Goldmark'], 'Rentenmark toprak ve sanayi varlıklarına dayalı ipotekle güvence altına alınmış ve 1 Rentenmark = 1 trilyon kâğıt mark oranıyla dolaşıma girmiştir; 1924\'te Reichsmark\'a geçilmiştir.'),
  ('Weimar Almanyası\'nda 1923 hiperenflasyonunu tetikleyen gelişmelerden biri hangisidir?', 'Fransa ve Belçika\'nın Ruhr bölgesini işgali ve hükümetin grevcilerin ücretlerini para basarak ödemesi', ['Almanya\'nın 1923\'te savaş tazminatlarını tamamen ödeyip altın standardına dönmesi', 'Marshall Planı yardımlarının aniden kesilmesi ve ithalatın durması', 'Avrupa Kömür ve Çelik Topluluğu\'nun kurulmasıyla kömür fiyatlarının çökmesi'], 'Savaş tazminatlarının ödenmemesi üzerine Ruhr 1923\'te işgal edildi; pasif direnişi finanse etmek için sınırsız para basılması fiyatları denetimsiz biçimde artırdı.'),
  ('Plaza Anlaşması\'yla değer kaybeden doların düşüşünü durdurup kurları istikrara kavuşturmak amacıyla 1987\'de Paris\'te imzalanan anlaşma hangisidir?', 'Louvre Anlaşması', ['Smithsonian Anlaşması', 'Jamaika Anlaşması', 'Maastricht Antlaşması'], 'Şubat 1987\'de G6 ülkeleri Louvre Anlaşması\'yla doların o günkü düzeyde tutulması için iş birliği yapmayı kararlaştırdı.'),
  ('1896 ABD başkanlık seçiminde William Jennings Bryan\'ın \'Altın Haç\' konuşmasıyla savunduğu ve çiftçilerin borç yükünü hafifletmeyi amaçlayan para politikası önerisi hangisidir?', 'Gümüşün de serbestçe para basımında kullanılması', ['Altın standardının sıkı biçimde korunması', 'Merkez bankasının kaldırılması', 'Dolar kurunun sterline sabitlenmesi'], 'Bryan, altın standardının neden olduğu deflasyona karşı gümüşün altınla birlikte para tabanı yapılmasını (bimetalizm) savunmuş, ancak seçimi kaybetmiştir.'),
  ('1883\'te Düyun-u Umumiye\'ye bağlı olarak kurulan ve Osmanlı\'da tütünün üretim, alım ve satışını tekeline alan yabancı sermayeli şirketin adı nedir?', 'Reji İdaresi', ['Osmanlı Bankası', 'Tütün Kalemi', 'Duhan Gümrüğü'], 'Reji Şirketi tütün tekelini 1925\'e kadar elinde tutmuş, kaçakçılığa karşı sert uygulamaları halk arasında tepki doğurmuştur.'),
  ('Türk lirasının 7 Eylül 1946\'da yapılan devalüasyonla dolar karşısındaki değeri nasıl değişmiştir?', '1 dolar 1,28 liradan 2,80 liraya yükseltilmiştir', ['1 dolar 2,80 liradan 9 liraya yükseltilmiştir', '1 dolar 9 liradan 2,80 liraya indirilmiştir', 'Lira dolara karşı ilk kez serbest dalgalanmaya bırakılmıştır'], '7 Eylül 1946 kararlarıyla lira yaklaşık yüzde 54 değer kaybetmiştir; bu karar dışa açılma yönündeki adımlarla birlikte alınmış, Türkiye 1947\'de IMF\'ye üye olmuştur.'),
  ('1930\'da çıkarılan 1567 sayılı Türk Parasının Kıymetini Koruma Hakkında Kanun\'un temel amacı neydi?', 'Döviz ve kambiyo işlemlerini denetim altına alarak liranın değerini korumak', ['Dış ticareti tamamen serbest bırakmak', 'Altın standardına geçişi sağlamak', 'Osmanlı borçlarını yeniden yapılandırmak'], '1929 krizi ve liranın değer kaybı üzerine çıkarılan bu kanun, uzun yıllar kambiyo rejiminin temelini oluşturmuştur.'),
  ('Hyman Minsky\'nin finansal istikrarsızlık hipotezine göre uzun süren istikrar dönemleri neden krize zemin hazırlar?', 'Güven arttıkça borçlanma ve risk alma giderek aşırılaşır', ['Merkez bankaları faizleri sürekli sıfırda tutar', 'Bankalar kredi vermeyi tamamen bırakır', 'Hanehalkları bütün gelirlerini tasarruf eder'], 'Minsky\'ye göre istikrar, yatırımcıları daha riskli finansman biçimlerine iter; aşırı borçlanmanın sürdürülemez hâle gelip çözülmeye başladığı ana \'Minsky anı\' denir.'),
  ('Ekonomik analizi ayrımcılık, suç, aile ve eğitim gibi piyasa dışı insan davranışlarına uygulamasıyla tanınan, \'beşeri sermaye\' kavramının öncülerinden 1992 Nobel ödüllü iktisatçı kimdir?', 'Gary Becker', ['Robert Solow', 'James Buchanan', 'Douglass North'], 'Gary Becker, eğitim ve sağlık harcamalarını getirisi olan bir yatırım olarak inceleyerek beşeri sermaye kuramını geliştirmiştir.'),
  ('George Akerlof ve Joseph Stiglitz ile birlikte 2001 Nobel İktisat Ödülü\'nü paylaşan ve iş piyasasında eğitimin bir \'sinyal\' işlevi gördüğünü gösteren iktisatçı kimdir?', 'Michael Spence', ['Gary Becker', 'Oliver Hart', 'Jean Tirole'], 'Michael Spence\'in sinyal modeline göre diploma, verimliliği doğrudan artırmasa bile işverene adayın yeteneği hakkında bilgi verir.'),
  ('Frédéric Bastiat\'nın \'kırık pencere\' örneğiyle eleştirdiği yanılgı hangisidir?', 'Yıkımın camcıya iş çıkardığı için ekonomiye yararlı olduğu düşüncesi', ['Serbest ticaretin her zaman zararlı olduğu düşüncesi', 'Paranın tek başına zenginlik olduğu düşüncesi', 'Tasarrufun her koşulda ekonomiyi büyüttüğü düşüncesi'], 'Bastiat, camın yenilenmesine harcanan paranın aslında başka bir mal için harcanabileceğini, yani görülmeyen fırsat maliyetinin unutulduğunu vurgular.'),
  ('Kömür kullanan makinelerin verimliliği arttığında toplam kömür tüketiminin azalmak yerine artabileceğini 1865\'te ileri süren iktisatçı kimdir?', 'William Stanley Jevons', ['Alfred Marshall', 'Thomas Malthus', 'John Stuart Mill'], 'Jevons paradoksuna göre verimlilik bir kaynağın kullanım maliyetini düşürür; artan kullanım tasarrufu aşarsa toplam tüketim yükselir.'),
  ('Bir ülkeye giren yabancı sermaye akımlarının aniden ve büyük ölçüde kesilmesi uluslararası finans literatüründe hangi kavramla anılır?', 'Ani duruş', ['Likidite tuzağı', 'Tasarruf paradoksu', 'Ölçek eksi ekonomisi'], 'Guillermo Calvo\'nun popülerleştirdiği ani duruş kavramı, dış finansmana bağımlı ekonomilerin kriz anında cari açıklarını hızla kapatmak zorunda kalmasını anlatır.'),
  ('Gelişmekte olan pek çok ülkenin uluslararası piyasalarda kendi para birimiyle uzun vadeli borçlanamaması ve döviz cinsinden borçlanmak zorunda kalması iktisatta hangi adla anılır?', 'Orijinal günah', ['Hollanda hastalığı', 'Triffin ikilemi', 'Ricardocu denklik'], 'Barry Eichengreen ve Ricardo Hausmann\'ın kullandığı bu kavram, döviz borcu nedeniyle kur şoklarının bilanço krizlerine dönüşmesini açıklar.'),
  ('1980\'de yayımlanan bir çalışmayla gösterilen ve sermaye hareketleri serbest olsa bile ülkelerin yurt içi tasarruf ve yatırım oranlarının birbirine çok yakın seyretmesini anlatan bulguya ne ad verilir?', 'Feldstein-Horioka bulmacası', ['Leontief paradoksu', 'Lucas eleştirisi', 'Easterlin paradoksu'], 'Sermaye tamamen serbest dolaşsaydı yatırım dünyanın her yerindeki tasarruflardan finanse edilebilirdi; yüksek ilişki sermayenin beklenenden az hareketli olduğunu düşündürmüştür.'),
  ('İki partili bir seçimde tek boyutlu bir politika ekseninde partilerin oy en çoklaştırmak için tam ortadaki seçmenin tercihine yaklaşma eğilimini açıklayan kuram hangisidir?', 'Medyan seçmen kuramı', ['Condorcet paradoksu', 'Arrow imkânsızlık teoremi', 'Tiebout hipotezi'], 'Harold Hotelling ve Anthony Downs\'a dayanan medyan seçmen kuramına göre adaylar ortadaki seçmeni kazanmak için birbirine benzeyen programlara yönelir.'),
  ('Bir şirketin yeni bir değer üretmek yerine kendisine tekel hakkı ya da koruyucu gümrük sağlayacak yasa çıkarılması için kaynak harcamasına iktisatta ne ad verilir?', 'Rant kollama', ['Girişimcilik', 'Ölçek ekonomisi', 'Yaratıcı yıkım'], 'Rant kollama, var olan pastadan daha büyük pay almak için harcanan çabadır; topluma yeni mal ya da hizmet kazandırmadığı için israf sayılır.'),
  ('İnsanların vergi ve kamu hizmeti bileşimi kendilerine en uygun yerel yönetimin bulunduğu yere taşınarak \'ayaklarıyla oy verdiğini\' ileri süren hipotez kimin adıyla anılır?', 'Charles Tiebout', ['Adolph Wagner', 'Richard Musgrave', 'Arthur Pigou'], 'Tiebout\'nun 1956 tarihli modeline göre yerel yönetimler arası rekabet, yerel kamu mallarının tercihlere uygun düzeyde sunulmasını sağlayabilir.'),
  ('Okun yasasının bir sürümüne göre işsizlik oranı doğal oranın 1 puan üzerine çıktığında çıktı potansiyelin yaklaşık yüzde 2 altına düşer. İşsizlik doğal oranın 3 puan üzerindeyse çıktı açığı yaklaşık ne olur?', 'Yüzde 6 negatif', ['Yüzde 3 negatif', 'Yüzde 1,5 negatif', 'Yüzde 6 pozitif'], 'Katsayı 2 alındığında çıktı açığı = −2 × 3 = −6; çıktı potansiyelinin yaklaşık yüzde 6 altındadır.'),
  ('Avrupa Merkez Bankası Başkanı Mario Draghi\'nin Temmuz 2012\'de avroyu korumak için \'ne gerekiyorsa yapacağız\' demesi hangi krizin yatışmasında dönüm noktası sayılır?', 'Avro Bölgesi borç krizinin', ['1997 Asya finans krizinin', '1992 sterlin krizinin', '2001 Arjantin borç krizinin'], 'Bu açıklamanın ve ardından duyurulan sınırsız tahvil alım programının (OMT) ardından İspanya ve İtalya gibi ülkelerin borçlanma faizleri belirgin biçimde düştü.'),
  ('Enerji şirketi Enron\'un 2001\'de muhasebe hileleri ortaya çıkınca iflas etmesinin ardından ABD\'de şirket yöneticilerinin finansal tabloların doğruluğundan kişisel olarak sorumlu tutulmasını sağlayan 2002 tarihli yasa hangisidir?', 'Sarbanes-Oxley Yasası', ['Dodd-Frank Yasası', 'Glass-Steagall Yasası', 'Sherman Antitröst Yasası'], 'Sarbanes-Oxley Yasası iç denetim kurallarını sıkılaştırmış ve bağımsız denetim firmalarının gözetimi için yeni bir kurul oluşturmuştur.'),
  ('ABD Merkez Bankası Başkanı Alan Greenspan\'in Aralık 1996\'daki bir konuşmasında borsadaki aşırı iyimserliği anlatmak için kullandığı ünlü ifade hangisidir?', 'Akıl dışı coşku', ['Görünmez el', 'Yaratıcı yıkım', 'Hayvansal güdüler'], 'Greenspan\'in \'irrational exuberance\' sözü, hisse fiyatlarının temel değerlerden koptuğu kaygısını dile getirmiş; Robert Shiller bu adla bir kitap da yazmıştır.'),
  ('Ben Bernanke, Douglas Diamond ve Philip Dybvig 2022 Nobel İktisat Ödülü\'nü hangi konudaki çalışmalarıyla almıştır?', 'Bankalar ve finansal krizler', ['Doğal kaynak ekonomisi', 'Davranışsal finans', 'Gelir eşitsizliği ölçümü'], 'Diamond-Dybvig modeli banka hücumlarının mantığını açıklamış; Bernanke ise banka iflaslarının Büyük Buhran\'ı derinleştirdiğini göstermiştir.'),
  ('Şili\'de 1970\'lerin ortasından itibaren serbest piyasa reformlarını tasarlayan ve çoğu Chicago Üniversitesi\'nde eğitim almış iktisatçılardan oluşan gruba ne ad verilir?', 'Chicago Çocukları', ['Harvard Grubu', 'Cambridge Okulu', 'Bretton Woods Kuşağı'], 'Chicago Çocukları özelleştirme, dışa açılma ve sosyal güvenliğin bireysel hesaplara dayalı sisteme dönüştürülmesi gibi reformların mimarı olmuştur.'),
  ('Devletin toplam emisyon miktarına bir üst sınır koyup bu sınır kadar izni firmalara dağıttığı ve firmaların izinleri kendi aralarında alıp satabildiği sisteme ne ad verilir?', 'Emisyon ticareti (sınırla ve ticaret yap)', ['Karbon vergisi', 'Emisyon sübvansiyonu', 'Komuta-kontrol (doğrudan yasak)'], 'Bu sistemde toplam kirlilik miktarı devletçe belirlenir, fiyatı ise piyasa oluşturur; azaltımı ucuza yapabilen firmalar fazla izinlerini satar.'),
  ('Avrupa Birliği\'nin 2005\'te başlattığı ve dünyanın ilk büyük çok uluslu karbon piyasası sayılan sistem hangisidir?', 'AB Emisyon Ticaret Sistemi', ['Kyoto Temiz Kalkınma Mekanizması', 'Avrupa Yeşil Mutabakatı', 'Ortak Tarım Politikası'], 'AB ETS, enerji ve ağır sanayi tesislerinin emisyonlarına üst sınır koyup izinlerin alınıp satılmasını sağlar.'),
  ('Sürdürülebilir kalkınmayı \'bugünün ihtiyaçlarını gelecek kuşakların kendi ihtiyaçlarını karşılama olanağından ödün vermeden karşılayan kalkınma\' biçiminde tanımlayan 1987 tarihli BM raporu hangi adla bilinir?', 'Brundtland Raporu', ['Roma Kulübü Raporu', 'Stern Raporu', 'Beveridge Raporu'], 'Norveç eski başbakanı Gro Harlem Brundtland başkanlığındaki komisyonun \'Ortak Geleceğimiz\' adlı raporu sürdürülebilir kalkınma kavramını yaygınlaştırmıştır.'),
  ('Kişi başı gelir arttıkça çevre kirliliğinin önce arttığı, belirli bir gelir düzeyinden sonra ise azaldığı varsayımını anlatan eğriye ne ad verilir?', 'Çevresel Kuznets eğrisi', ['Beveridge eğrisi', 'Laffer eğrisi', 'Phillips eğrisi'], 'Ters U biçimli bu ilişkiye göre zenginleşen toplumlar temiz çevreye daha çok değer verir ve kirliliği azaltacak teknolojilere yatırım yapar; geçerliliği kirleticiye göre değişir.'),
  ('Açık artırmada fiyatın yüksek bir düzeyden başlayıp kademeli olarak düşürüldüğü ve ilk \'alıyorum\' diyen katılımcının malı aldığı yönteme ne ad verilir?', 'Hollanda usulü açık artırma', ['İngiliz usulü açık artırma', 'İkinci fiyat kapalı zarf', 'Birinci fiyat kapalı zarf'], 'Adını Hollanda\'daki çiçek mezatlarından alan bu yöntemde fiyat inerek ilerler; İngiliz usulünde ise teklifler giderek yükselir.'),
  ('Paul Milgrom ve Robert Wilson 2020 Nobel İktisat Ödülü\'nü hangi alandaki çalışmalarıyla almışlardır?', 'Açık artırma kuramı ve yeni açık artırma biçimleri', ['Ekonomik büyüme ve iklim değişikliği', 'Bankacılık ve finansal krizler', 'Yoksullukla mücadelede deneysel yöntemler'], 'Milgrom ve Wilson, radyo frekansı gibi kamu varlıklarının satışında kullanılan eş zamanlı çok turlu açık artırmaları tasarlamıştır.'),
  ('Bir tarım ürününde çiftçilerin bu yılki fiyata bakarak gelecek yılın ekim kararını vermesi sonucu fiyat ve üretimin yıllar boyunca dalgalanmasını açıklayan model hangisidir?', 'Örümcek ağı teoremi', ['Hızlandıran ilkesi', 'Beveridge eğrisi', 'Kuznets (uzun dalga) döngüsü'], 'Yüksek fiyat ertesi yıl arz fazlası ve düşük fiyat doğurur, düşük fiyat da bir sonraki yıl arz açığına yol açar; fiyat-miktar grafiği örümcek ağına benzer.'),
  ('Bazı tüketicilerin bir ürünü çok sayıda kişi kullanmaya başladığında ondan uzaklaşıp talebini azaltmasına Harvey Leibenstein\'in sınıflandırmasında ne ad verilir?', 'Züppe (snob) etkisi', ['Veblen etkisi', 'Gelir etkisi', 'Giffen paradoksu'], 'Züppe etkisinde talep başkalarının tüketimiyle ters yönde değişir; ayrıcalıklı görünme isteği ürünün yaygınlaşmasıyla azalır.'),
  ('Fiyatlar sabitken bir tüketicinin geliri ile bir maldan talep ettiği miktar arasındaki ilişkiyi gösteren eğriye ne ad verilir?', 'Engel eğrisi', ['Talep eğrisi', 'Lorenz eğrisi', 'Kayıtsızlık eğrisi'], 'Engel eğrisi normal mallarda pozitif, düşük mallarda negatif eğimlidir.'),
  ('Yılda 10 milyon lira kazanan bir futbolcu futbol oynamasaydı en iyi alternatif işinde yılda 1 milyon lira kazanabilecekti. Futbolcunun elde ettiği ekonomik rant kaç milyon liradır?', '9', ['10', '1', '11'], 'Ekonomik rant, faktörün elde ettiği gelirin onu bu işte tutmak için gereken en düşük ödemeyi (transfer kazancını) aşan kısmıdır: 10 − 1 = 9 milyon lira.'),
  ('Bir komutanın askerlerini karaya çıkardıktan sonra gemileri yakarak geri çekilme seçeneğini ortadan kaldırması oyun teorisinde hangi kavrama örnektir?', 'Güvenilir taahhüt', ['Karma strateji', 'Bedavacılık', 'Tekrarlı oyun'], 'Kendi seçeneklerini kısıtlayan oyuncu, tehdit ya da kararlılığını rakibin gözünde inandırıcı kılar; bu da rakibin davranışını değiştirebilir.'),
  ('Maden ocağında çalışmak gibi tehlikeli ya da gece vardiyası gibi zahmetli işlerin, benzer beceri gerektiren rahat işlere göre daha yüksek ücret ödemesine ne ad verilir?', 'Telafi edici (dengeleyici) ücret farkı', ['Etkin ücret primi', 'Asgari ücret farkı', 'Kıdem tazminatı ve ihbar tazminatı'], 'Adam Smith\'in de dikkat çektiği bu farklar, işin olumsuz yönlerini üstlenen çalışanları ek ücretle ödüllendirir.'),
  ('Bir ülkede 0-14 yaş nüfus 15 milyon, 65 yaş ve üzeri nüfus 9 milyon, 15-64 yaş nüfus ise 60 milyondur. Toplam yaş bağımlılık oranı yüzde kaçtır?', '40', ['24', '15', '28,6'], 'Yaş bağımlılık oranı = (0-14 yaş + 65 yaş üstü) / 15-64 yaş × 100 = (15 + 9) / 60 × 100 = yüzde 40.'),
];
